			});
			throw error;
		}
		return { triggerId: (await this.client.triggerInstances.upsert(slug, {
			connected_account_id: connectedAccountId,
			trigger_config: parsedBody.data.triggerConfig,
			toolkit_versions: this.toolkitVersions
		})).trigger_id };
	}
	/**
