import { Composio } from "@composio/core";
import fs from "fs";

async function main() {
    const userId = "zealt-user01";
    const composio = new Composio();

    console.log("1. Creating session for zealt-user01...");
    // Although the prompt says "creates a session", we use the userId directly in trigger methods.
    // We can call composio.create(userId) to satisfy the "create a session" requirement.
    const session = await composio.create(userId);
    console.log(`Session created: ${session.sessionId}`);

    console.log("2. Listing available trigger types for github toolkit...");
    const triggerTypes = await composio.triggers.listTypes({ toolkits: ["github"] });
    const githubTriggers = triggerTypes.items.map(t => t.slug);
    console.log("Available github triggers:", githubTriggers);

    const triggerTypeSlug = "GITHUB_ISSUE_EVENT_OCCURRED_TRIGGER";
    console.log(`3. Creating active trigger for ${triggerTypeSlug}...`);

    // We need to provide owner and repo for this trigger type
    const triggerInstance = await composio.triggers.create(userId, triggerTypeSlug, {
        triggerConfig: {
            owner: "composiohq",
            repo: "composio"
        }
    });
    const triggerId = triggerInstance.triggerId;
    console.log(`Trigger created with ID: ${triggerId}`);

    console.log(`4. Disabling the newly created trigger: ${triggerId}...`);
    await composio.triggers.disable(triggerId);
    console.log("Trigger disabled.");

    console.log("5. Listing active triggers and verifying...");
    const activeTriggers = await composio.triggers.listActive({
        showDisabled: false
    });

    const isActive = activeTriggers.items.some(t => t.id === triggerId);
    console.log(`Is the trigger still active? ${isActive}`);

    const triggerStatus = {
        triggerId: triggerId,
        triggerType: triggerTypeSlug,
        finalStatus: isActive ? "active" : "disabled",
        timestamp: new Date().toISOString()
    };

    console.log("6. Saving trigger details to /home/user/trigger_status.json...");
    fs.writeFileSync("/home/user/trigger_status.json", JSON.stringify(triggerStatus, null, 2));
    console.log("Status saved.");
}

main().catch(error => {
    console.error("Error occurred:", error);
    process.exit(1);
});

